            return false;
        }
        let path = self.base.join(relative);
        let decided_inside = path.ancestors().skip(1).take_while(|dir| dir.starts_with(&self.base)).any(|dir| {
            self.inside_rules(dir).verdict(&path, is_dir).is_some()
        });
        if decided_inside {
            return false;
        }
        self.parents.iter().find_map(|rules| rules.verdict(&path, is_dir)).unwrap_or(false)
    }

